164	/// Handle for controlling a spinner.
165	pub trait SpinnerHandle {
166	    /// Update the spinner message.
167	    fn set_message(&mut self, msg: &str);
168	
169	    /// Mark the operation as successful.
170	    fn finish_success(&mut self, msg: &str);
171	
172	    /// Mark the operation as failed.
173	    fn finish_error(&mut self, msg: &str);
174	
175	    /// Mark as skipped.
176	    fn finish_skipped(&mut self, msg: &str);
177	
178	    /// Clear the spinner without leaving any output.
179	    fn finish_and_clear(&mut self);
180	
181	    /// Get a clone of the underlying progress bar, if available.
182	    ///
183	    /// This is used for live output streaming: the cloned bar can be shared
184	    /// with an `OutputCallback` to update the spinner message in real-time.
185	    /// Returns `None` for mock/hidden spinners.
186	    fn progress_bar(&self) -> Option<ProgressBar> {
187	        None
188	    }
189	}
