278	        callback.write_line(OutputLine::Stdout("real output".to_string()));
279	        let msg = bar.message();
280	        assert!(msg.contains("real output"));
281	        // Only one newline (base message + one output line)
282	        assert_eq!(msg.matches('\n').count(), 1);
283	
284	        bar.finish();
285	    }
286	
287	    #[test]
288	    fn live_output_callback_truncates_long_lines() {
289	        let bar = ProgressBar::hidden();
290	        let callback = live_output_callback(bar.clone(), "Running...".to_string(), 4, 2);
291	
292	        let long_line = "x".repeat(100);
293	        callback.write_line(OutputLine::Stdout(long_line));
294	        let msg = bar.message();
295	        assert!(msg.contains("..."));
296	        // Should not contain the full 100-char line
297	        assert!(!msg.contains(&"x".repeat(100)));
298	
299	        bar.finish();
300	    }
301	}
