    #[test]
    fn prompt_recovery_multi_limits_fixes_to_three() {
        let mut ui = MockUI::new();
        ui.set_interactive(true);
        // Try to select the 4th fix: only 3 are offered (fix_0..fix_2),
        // so the 4th high-confidence resolution overflows to suggestion (fix_3).
        // We verify the first 3 are fixes and the 4th is available as suggestion.
        ui.set_prompt_response("recovery_test", "fix_3");

        let resolutions = vec![
            make_resolution("fix1", "cmd1", 0.9),
            make_resolution("fix2", "cmd2", 0.8),
            make_resolution("fix3", "cmd3", 0.7),
            make_resolution("fix4", "cmd4", 0.65), // 4th high-confidence → becomes suggestion
        ];

        let action =
            prompt_recovery_multi(&mut ui, "test", &resolutions, &HashSet::new(), 0).unwrap();
        // fix_3 maps to the overflowed suggestion
        assert_eq!(action, RecoveryAction::Fix("cmd4".to_string()));
    }

    #[test]
    fn prompt_recovery_multi_caps_total_options() {
        let mut ui = MockUI::new();
        ui.set_interactive(true);
        // 3 fixes + 2 suggestions = 5 total. 6th should not be offered.
        ui.set_prompt_response("recovery_test", "fix_5");

        let resolutions = vec![
            make_resolution("fix1", "cmd1", 0.9),
            make_resolution("fix2", "cmd2", 0.8),
            make_resolution("fix3", "cmd3", 0.7),
            make_resolution("sug1", "cmd4", 0.5),
            make_resolution("sug2", "cmd5", 0.4),
            make_resolution("sug3", "cmd6", 0.35), // Should be capped
        ];

        let action =
            prompt_recovery_multi(&mut ui, "test", &resolutions, &HashSet::new(), 0).unwrap();
        // fix_5 doesn't exist, falls through to Retry
        assert_eq!(action, RecoveryAction::Retry);
    }

    #[test]
    fn prompt_recovery_multi_shows_suggestions_for_medium_confidence() {
        let mut ui = MockUI::new();
        ui.set_interactive(true);
        // fix_0 is the suggestion (medium confidence, no high-confidence fixes)
        ui.set_prompt_response("recovery_test", "fix_0");

        let resolutions = vec![make_resolution(
            "check requirements.txt",
            "pip install -r requirements.txt",
            0.45,
        )];

        let action =
            prompt_recovery_multi(&mut ui, "test", &resolutions, &HashSet::new(), 0).unwrap();
        assert_eq!(
            action,
            RecoveryAction::Fix("pip install -r requirements.txt".to_string())
        );
    }

    #[test]
    fn prompt_recovery_multi_skips_fix_in_history() {
        let mut ui = MockUI::new();
        ui.set_interactive(true);
        // Only retry is available since the fix is in history
        ui.set_prompt_response("recovery_test", "retry");

        let resolutions = vec![make_resolution("install pkg", "apt install pkg", 0.8)];

        let mut history = HashSet::new();
        history.insert("apt install pkg".to_string());

        let action = prompt_recovery_multi(&mut ui, "test", &resolutions, &history, 0).unwrap();
        assert_eq!(action, RecoveryAction::Retry);
    }

    #[test]
    fn prompt_recovery_multi_custom_fix() {
        let mut ui = MockUI::new();
        ui.set_interactive(true);
        ui.queue_prompt_responses("recovery_test", vec!["custom_fix"]);
        ui.set_prompt_response("custom_fix_test", "my custom command");

        let resolutions = vec![make_resolution("some fix", "some cmd", 0.7)];

        let action =
            prompt_recovery_multi(&mut ui, "test", &resolutions, &HashSet::new(), 0).unwrap();
        assert_eq!(
            action,
            RecoveryAction::CustomFix("my custom command".to_string())
        );
    }

    #[test]
    fn prompt_recovery_multi_skip() {
        let mut ui = MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("recovery_test", "skip");

        let resolutions = vec![make_resolution("fix", "cmd", 0.7)];

        let action =
            prompt_recovery_multi(&mut ui, "test", &resolutions, &HashSet::new(), 0).unwrap();
        assert_eq!(action, RecoveryAction::Skip);
    }

    #[test]
    fn prompt_recovery_multi_abort() {
        let mut ui = MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("recovery_test", "abort");

        let resolutions = vec![make_resolution("fix", "cmd", 0.7)];

        let action =
            prompt_recovery_multi(&mut ui, "test", &resolutions, &HashSet::new(), 0).unwrap();
        assert_eq!(action, RecoveryAction::Abort);
    }

    #[test]
    fn prompt_recovery_multi_no_custom_fix_without_resolutions() {
        let mut ui = MockUI::new();
        ui.set_interactive(true);
        // With no resolutions, "custom_fix" shouldn't be offered
        ui.set_prompt_response("recovery_test", "skip");

        let action = prompt_recovery_multi(&mut ui, "test", &[], &HashSet::new(), 0).unwrap();
        assert_eq!(action, RecoveryAction::Skip);
    }

    #[test]
    fn prompt_recovery_multi_advisory_only_resolutions_show_custom_fix() {
        let mut ui = MockUI::new();
        ui.set_interactive(true);
        ui.queue_prompt_responses("recovery_test", vec!["custom_fix"]);
        ui.set_prompt_response("custom_fix_test", "manual fix");

        // Advisory-only resolution (no command) — still enables custom fix option
        let resolutions = vec![ResolutionCandidate {
            label: "check service logs".to_string(),
            command: None,
            explanation: "The service may have crashed".to_string(),
            confidence: 0.5,
            source: crate::runner::diagnostic::ResolutionSource::Deduced,
            platform: None,
        }];

        let action =
            prompt_recovery_multi(&mut ui, "test", &resolutions, &HashSet::new(), 0).unwrap();
        assert_eq!(action, RecoveryAction::CustomFix("manual fix".to_string()));
    }
}

//! Run-path display layer.
//!
//! This module provides the rendering contracts for a workflow run:
//!
//! - [`WorkflowDisplay`] — workflow chrome (run header, pinned progress
//!   bar, run summary).
//! - [`StepDisplay`] — per-step rendering (step header, transient
//!   spinner with live-output tail, error block, prompts, final result
//!   line).
//!
//! Both contracts live here, not in `ui/`, because they are concerns of
//! the workflow runner and depend on workflow types
//! ([`RunSummary`], [`StepSummary`], [`RunHeader`]). The `ui/` crate
//! provides only generic primitives — most importantly
//! [`crate::ui::surface::TerminalSurface`].
//!
//! ## Why split workflow vs step?
//!
//! The original `TerminalUI` owned the workflow's `MultiProgress` and
//! also handed out spinners that lived inside it. Step code could
//! therefore mutate the same draw region as the workflow bar, which
//! made the multi-line spinner clearing bug observable: a step's
//! lingering rows would corrupt the workflow chrome.
//!
//! With this split, each layer owns its own region:
//!
//! - `TerminalWorkflowDisplay` owns the pinned bar.
//! - `TerminalStepDisplay` owns a transient region that lives above
//!   the pinned bar.
//! - Both share an `Arc<TerminalSurface>`; only the surface touches the
//!   underlying `MultiProgress`.

pub mod step;
pub mod workflow;

use std::time::Duration;

use crate::ui::StatusKind;

pub use step::{NonInteractiveStepDisplay, StepDisplay, TerminalStepDisplay};
pub use workflow::{
    MockState, MockStepDisplay, MockWorkflowDisplay, NonInteractiveWorkflowDisplay,
    TerminalWorkflowDisplay, WorkflowDisplay,
};

/// Header shown at the top of a workflow run.
#[derive(Debug, Clone)]
pub struct RunHeader {
    /// Application name shown alongside the lodge icon.
    pub app_name: String,
    /// Bivvy version string.
    pub version: String,
    /// Workflow name (e.g. `default`).
    pub workflow: String,
    /// Total step count to run.
    pub step_count: usize,
    /// Active environment label (e.g. `development`).
    pub env_name: String,
}

/// Summary of a workflow run, used by [`WorkflowDisplay::show_run_summary`].
#[derive(Debug, Clone)]
pub struct RunSummary {
    /// Per-step results in execution order.
    pub step_results: Vec<StepSummary>,
    /// Total run duration.
    pub total_duration: Duration,
    /// Number of steps that ran.
    pub steps_run: usize,
    /// Number of steps skipped.
    pub steps_skipped: usize,
    /// Number of steps auto-skipped because already satisfied.
    pub steps_satisfied: usize,
    /// Whether all steps succeeded.
    pub success: bool,
    /// Names of failed steps.
    pub failed_steps: Vec<String>,
}

/// Summary of a single step's result.
#[derive(Debug, Clone)]
pub struct StepSummary {
    /// Step name.
    pub name: String,
    /// Step status.
    pub status: StatusKind,
    /// How long the step took.
    pub duration: Option<Duration>,
    /// Additional context (e.g., check description like "rustc --version").
    pub detail: Option<String>,
}

