111	    fn show_run_header(&mut self, hdr: &RunHeader) {
112	        if !self.mode.shows_status() {
113	            return;
114	        }
115	        let step_label = if hdr.step_count == 1 { "step" } else { "steps" };
116	        self.surface.println(&format!(
