200	            String::new()
201	        };
202	        lines.push(
203	            b.apply_to("├────────────────────────────────────")
204	                .to_string(),
205	        );
206	        lines.push(format!(
207	            "{} Total: {} {} {} run {} {} skipped{}",
208	            b.apply_to("│"),
209	            self.theme
210	                .duration
211	                .apply_to(format_duration(summary.total_duration)),
212	            self.theme.dim.apply_to("·"),
213	            summary.steps_run,
214	            self.theme.dim.apply_to("·"),
215	            summary.steps_skipped,
216	            satisfied_part,
217	        ));
218	        lines.push(
219	            b.apply_to("└────────────────────────────────────")
220	                .to_string(),
221	        );
222	
223	        for line in &lines {
224	            self.surface.println(line);
225	        }
226	    }
227	
228	    fn begin_step(&mut self, index: usize, total: usize) -> Box<dyn StepDisplay> {
229	        Box::new(TerminalStepDisplay::new(
230	            Arc::clone(&self.surface),
231	            self.mode,
232	            index,
233	            total,
234	        ))
235	    }
236	
237	    fn message(&mut self, msg: &str) {
238	        if self.mode.shows_status() {
239	            self.surface.println(msg);
240	        }
241	    }
242	
243	    fn hint(&mut self, hint: &str) {
244	        if !self.mode.shows_status() {
245	            return;
246	        }
247	        self.surface
248	            .println(&self.theme.hint.apply_to(hint).to_string());
249	        self.surface.println("");
250	    }
251	}
