280	impl WorkflowDisplay for NonInteractiveWorkflowDisplay {
281	    fn show_run_header(&mut self, hdr: &RunHeader) {
282	        if !self.mode.shows_status() {
283	            return;
284	        }
285	        let step_label = if hdr.step_count == 1 { "step" } else { "steps" };
286	        println!(
287	            "\n⛺ {} v{} · {} workflow · {} {} · env: {}\n",
288	            hdr.app_name, hdr.version, hdr.workflow, hdr.step_count, step_label, hdr.env_name,
289	        );
290	    }
291	
292	    fn start_progress(&mut self, _total: usize) {}
293	
294	    fn update_progress(&mut self, current: usize, total: usize, elapsed: Duration) {
295	        if self.is_ci {
296	            return;
297	        }
298	        if !self.mode.shows_status() {
299	            return;
300	        }
301	        let filled = current
302	            .checked_mul(16)
303	            .and_then(|v| v.checked_div(total))
304	            .unwrap_or(0);
305	        let empty = 16usize.saturating_sub(filled);
306	        let bar = format!("{}{}", "█".repeat(filled), "░".repeat(empty));
307	        println!(
308	            "  [{}] {}/{} steps · {} elapsed",
309	            bar,
310	            current,
311	            total,
312	            format_duration(elapsed),
313	        );
314	    }
315	
316	    fn finish_progress(&mut self) {}
317	
318	    fn show_run_summary(&mut self, summary: &RunSummary) {
319	        if !self.mode.shows_status() {
320	            return;
321	        }
322	
323	        println!();
324	        println!("  ┌─ Summary ──────────────────────────");
325	
326	        for step in &summary.step_results {
327	            let icon = step.status.icon();
328	            let duration_str = step.duration.map(format_duration).unwrap_or_default();
329	            let detail_str = step.detail.as_deref().unwrap_or("");
330	
331	            let right_side = if !duration_str.is_empty() {
332	                duration_str
333	            } else if !detail_str.is_empty() {
334	                detail_str.to_string()
335	            } else {
336	                String::new()
337	            };
338	
339	            println!("  │ {} {:<20} {}", icon, step.name, right_side);
340	        }
341	
342	        println!("  ├────────────────────────────────────");
343	        let satisfied_part = if summary.steps_satisfied > 0 {
344	            format!(" · {} already satisfied", summary.steps_satisfied)
345	        } else {
346	            String::new()
347	        };
348	        println!(
349	            "  │ Total: {} · {} run · {} skipped{}",
350	            format_duration(summary.total_duration),
351	            summary.steps_run,
352	            summary.steps_skipped,
353	            satisfied_part,
354	        );
355	        println!("  └────────────────────────────────────");
356	        // No trailing "Setup complete!" / "Setup failed" line — see the
357	        // matching note in `TerminalWorkflowDisplay::show_run_summary`.
358	    }
359	
360	    fn begin_step(&mut self, index: usize, total: usize) -> Box<dyn StepDisplay> {
361	        Box::new(NonInteractiveStepDisplay::new(self.mode, index, total))
362	    }
363	
364	    fn message(&mut self, msg: &str) {
365	        if self.mode.shows_status() {
366	            println!("{}", msg);
367	        }
368	    }
369	
370	    fn hint(&mut self, hint: &str) {
371	        if self.mode.shows_status() {
372	            println!("  💡 {}", hint);
373	        }
374	    }
375	}
