        name: self.step_name.to_string(),
        reason: eval_result.reason.clone(),
    });
    event_bus.emit(&BivvyEvent::StepOutcome {
        name: self.step_name.to_string(),
        outcome: StepOutcomeKind::Satisfied,
        detail: Some(eval_result.reason.clone()),
        duration_ms: None,
    });
